"""Scene state storage and turn persistence for rehearsal (spec/02 §2.2, T19).

Stores ongoing interactive rehearsal scenes and turn-by-turn history,
including tagged acts, child responses, generated lines, and stage timing metrics.
"""

from __future__ import annotations

import logging
from datetime import UTC, datetime
from uuid import UUID, uuid4

from pydantic import BaseModel, Field

from backend.app.rule_engine.domain import ChildResponse, SceneState

logger = logging.getLogger("abhyas.rehearsal.scene_store")


class ChildLineRecord(BaseModel):
    """Spoken child line generated by child_voice with audio metadata."""

    persona_id: str
    line_hi: str
    voice_id: str
    audio_ref: str | None = None  # Cache key or storage ref of synthesized audio


class TurnRecord(BaseModel):
    """Full record of one turn in a rehearsal scene (spec/02 §2.2)."""

    turn_index: int
    transcript: str
    acts: list[str]
    addressed_child: str | None = None
    child_responses: list[ChildResponse] = Field(default_factory=list)
    child_lines: list[ChildLineRecord] = Field(default_factory=list)
    stage_ms: dict[str, int] = Field(default_factory=dict)
    ended: bool = False
    end_reason: str | None = None
    created_at: datetime = Field(default_factory=lambda: datetime.now(UTC))


class SceneRecord(BaseModel):
    """Full snapshot of an interactive rehearsal scene (spec/02 §2.2)."""

    scene_id: UUID = Field(default_factory=uuid4)
    teacher_id: UUID
    move_id: str
    scene_state: SceneState
    turns: list[TurnRecord] = Field(default_factory=list)
    active: bool = True
    created_at: datetime = Field(default_factory=lambda: datetime.now(UTC))
    updated_at: datetime = Field(default_factory=lambda: datetime.now(UTC))


class SceneStore:
    """Thread-safe in-memory store for active rehearsal scenes."""

    def __init__(self) -> None:
        self._scenes: dict[UUID, SceneRecord] = {}
        self._teacher_active_scenes: dict[UUID, UUID] = {}

    def save(self, scene: SceneRecord) -> None:
        """Persists or updates a scene record."""
        scene.updated_at = datetime.now(UTC)
        self._scenes[scene.scene_id] = scene
        if scene.active:
            self._teacher_active_scenes[scene.teacher_id] = scene.scene_id
        elif self._teacher_active_scenes.get(scene.teacher_id) == scene.scene_id:
            del self._teacher_active_scenes[scene.teacher_id]

    def get(self, scene_id: UUID) -> SceneRecord | None:
        """Retrieves a scene record by ID."""
        return self._scenes.get(scene_id)

    def get_active_for_teacher(self, teacher_id: UUID) -> SceneRecord | None:
        """Retrieves currently active scene for a teacher, if any."""
        scene_id = self._teacher_active_scenes.get(teacher_id)
        if scene_id is not None:
            return self._scenes.get(scene_id)
        return None

    def clear(self) -> None:
        """Clears all stored scenes (for test isolation)."""
        self._scenes.clear()
        self._teacher_active_scenes.clear()


# Global singleton instance
scene_store = SceneStore()


__all__ = [
    "ChildLineRecord",
    "TurnRecord",
    "SceneRecord",
    "SceneStore",
    "scene_store",
]
